Act: bash

```bash
cat > tests/examples.json << 'EOF'
{
  "examples": [
    {
      "input_date": "2023-5-1",
      "format_string": "%Y/%m/%d",
      "expected_output": "2023/05/01"
    },
    {
      "input_date": "12/25/2023",
      "format_string": "%B %d, %Y",
      "expected_output": "December 25, 2023"
    },
    {
      "input_date": "2023-01-15",
      "format_string": "%b %d, %y",
      "expected_output": "Jan 15, 23"
    },
    {
      "input_date": "3/7/2024",
      "format_string": "%Y-%m-%d",
      "expected_output": "2024-03-07"
    },
    {
      "input_date": "2023-12-31",
      "format_string": "%d/%m/%Y",
      "expected_output": "31/12/2023"
    },
    {
      "input_date": "6/4/2023",
      "format_string": "%B %Y",
      "expected_output": "June 2023"
    }
  ]
}
EOF
```

